command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "a68626830efb6e251c43d4667b4cae93bb35885c") { throw "main moved" }
git -C $env:GITHUB_WORKSPACE push origin --delete work/validation-churn-guards
if ($LASTEXITCODE -ne 0) { throw "work branch cleanup failed" }
Write-Host "VALIDATION_CHURN_GUARDS_WORK_BRANCH_DELETED"
